style.css:
/* Dark Cacao Wallpaper for YouTube /
body {
margin: 0;
padding: 0;
height: 100vh; / Fill the viewport height /
background-color: #3E2723; / Dark cacao color /
background-image: url('path-to-your-cacao-texture.png'); / Optional: Add a cacao texture image /
background-size: cover; / Cover the entire body /
background-position: center; / Center the background image /
display: flex; / Use flexbox for centering content /
align-items: center; / Center vertically /
justify-content: center; / Center horizontally /
font-family: 'Arial', sans-serif; / Default font /
color: #D7CCC8; / Light cacao color for text /
text-align: center; / Center text */
/* Styles for headings /
h1 {
font-size: 2.5rem; / Responsive heading size /
margin: 0 0 20px; / Margin below the heading */
/* Styles for paragraphs /
p {
font-size: 1.2rem; / Responsive paragraph size /
max-width: 600px; / Max width for readability /
line-height: 1.5; / Line height for readability */
